library ieee; use ieee.std_logic_1164.all; use ieee.numeric_std.all;
entity bbq_divider_core is generic(WIDTH:positive:=32);port(clk,rst_n,start:in std_logic;dividend,divisor:in std_logic_vector(WIDTH-1 downto 0);busy,done,divide_by_zero:out std_logic;quotient,remainder:out std_logic_vector(WIDTH-1 downto 0));end;
architecture rtl of bbq_divider_core is signal q,d:unsigned(WIDTH-1 downto 0):=(others=>'0');signal r:unsigned(WIDTH downto 0):=(others=>'0');signal idx:natural range 0 to WIDTH:=0;signal b,fin,z:std_logic:='0';begin quotient<=std_logic_vector(q);remainder<=std_logic_vector(r(WIDTH-1 downto 0));busy<=b;done<=fin;divide_by_zero<=z;process(clk)variable rn:unsigned(WIDTH downto 0);variable qn:unsigned(WIDTH-1 downto 0);begin if rising_edge(clk)then fin<='0';if rst_n='0'then q<=(others=>'0');d<=(others=>'0');r<=(others=>'0');idx<=0;b<='0';z<='0';elsif start='1' and b='0'then z<='0';if unsigned(divisor)=0 then q<=(others=>'1');r(WIDTH-1 downto 0)<=unsigned(dividend);r(WIDTH)<='0';z<='1';fin<='1';else q<=unsigned(dividend);d<=unsigned(divisor);r<=(others=>'0');idx<=WIDTH;b<='1';end if;elsif b='1'then rn:=shift_left(r,1);rn(0):=q(WIDTH-1);qn:=shift_left(q,1);if rn>=('0'&d)then rn:=rn-('0'&d);qn(0):='1';end if;r<=rn;q<=qn;if idx=1 then idx<=0;b<='0';fin<='1';else idx<=idx-1;end if;end if;end if;end process;end architecture;
